sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    //cancel the flow context running on the outbound record

    var outboundRec = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_log');
    outboundRec.addQuery('type', 'Outbound');
    outboundRec.addQuery('trade_case_task_number', current.trade_case_task_number); // fetch the email log with same task number which we have received an inbound on
    outboundRec.query();

    while (outboundRec.next()) {
        var flowContext = new GlideRecord('sys_flow_context'); 
        flowContext.addQuery('source_record', outboundRec.sys_id);
		flowContext.addQuery('name', 'HSBC-Generic Follow up email'); //name=HSBC-Generic Follow up email
        flowContext.query();
        while (flowContext.next()) {
            sn_fd.FlowAPI.cancel(flowContext.getUniqueValue(), 'Cancelling in-progress');
        }
    }



})(current, previous);
